class DuckUser:
    pk = 1
    is_active = True
    def get_session_auth_hash(self):
        return "current-hash"

class Backend:
    def get_user(self, user_id):
        return DuckUser()

class FakeSession(dict):
    flushed = False
    def flush(self):
        self.flushed = True
        self.clear()
    def cycle_key(self):
        pass

class Req:
    pass

for stored_hash, label in [("current-hash", "matching hash"), ("stale-hash", "stale hash"), (None, "missing hash")]:
    r = Req()
    r.session = FakeSession({SESSION_KEY: "1", BACKEND_SESSION_KEY: "ducktype_check.Backend"})
    if stored_hash is not None:
        r.session[HASH_SESSION_KEY] = stored_hash
